import numpy as np


def bigram_probs(N, alpha):
    M = N + alpha
    return M / M.sum(axis=1, keepdims=True)


def nll(P, words):
    total, n = 0.0, 0
    for w in words:
        cs = "." + w + "."
        for a, b in zip(cs, cs[1:]):
            p = P[index[a], index[b]]
            if p == 0:
                continue
            total -= math.log(p)
            n += 1
    return total / n
